import {
  defineConfig,
  envField,
  fontProviders,
  passthroughImageService,
  svgoOptimizer
} from 'astro/config';
import { satteri } from '@astrojs/markdown-satteri';
import react from '@astrojs/react';
import icon from 'astro-icon';
import editableRegions from '@cloudcannon/editable-regions/astro-integration';
import mdx from '@astrojs/mdx';
import sitemap from '@astrojs/sitemap';
import AstroPWA from '@vite-pwa/astro';

import tailwindcss from '@tailwindcss/vite';
import RouteData from './data/routing.json';
// Generated by `pnpm seo:urls` (@ttp/seo-tools/url-history.mjs) — one 301 for every URL any contents
// entry has ever produced, so an edited slug cannot silently orphan its old
// URL. Hand-written rules in routing.json are applied last and win on conflict.
import UrlHistory from './data/url-history.json';
import { lastmodFor } from '@ttp/seo-tools/lib/lastmod.mjs';
import {
  alternatesFor,
  LOCALES,
  DEFAULT_LOCALE
} from '@ttp/seo-tools/lib/alternates.mjs';
import { noindexPathSet } from '@ttp/seo-tools/lib/routes.mjs';
import type { ValidRedirectStatus } from 'astro';
import { writeFile } from 'fs/promises';
import path from 'path';
import pagefind from 'astro-pagefind';

import { satteriExternalLinks } from './utils/satteri-external-links';

type RedirectRule = {
  from: string;
  destination: string;
  status: ValidRedirectStatus;
};

/**
 * Paths whose page renders `noindex`, read once from content frontmatter and
 * used by the sitemap filter below.
 */
const NOINDEX_PATHS: Set<string> = noindexPathSet();

/**
 * Netlify applies the first matching rule in _redirects, so precedence is
 * expressed by order: hand-written rules from routing.json come first and win,
 * generated history fills in behind them. Deduplication is by `from` alone —
 * two rules for the same source are a conflict, not two useful rules.
 */
function removeDuplicateRedirects(redirects: RedirectRule[]) {
  const seen = new Set<string>();
  const uniqueRedirects: RedirectRule[] = [];

  for (const redirect of redirects) {
    if (seen.has(redirect.from)) continue;
    seen.add(redirect.from);
    uniqueRedirects.push(redirect);
  }
  return uniqueRedirects;
}

// Generate denylist patterns from routing.json to exclude redirect paths from navigateFallback
const redirectDenylist = RouteData.routes.map((route) => {
  // Escape special regex characters and create exact match pattern
  const escapedPath = route.from.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp(`^${escapedPath}$`);
});

